struct ContentView: View {
    @State private var selection = 0
    var body: some View {
        TabView(selection: $selection) {
            NotesList().tabItem { Label("Notes", systemImage: "note.text") }.tag(0)
            TagsView().tabItem { Label("Tags", systemImage: "tag") }.tag(1)
            SettingsView().tabItem { Label("Settings", systemImage: "gear") }.tag(2)
        }
    }
}

struct NotesList: View {
    @State private var notes: [Note] = []
    var body: some View {
        NavigationStack {
            List(notes) { note in
                NavigationLink(note.title) { NoteDetail(note: note) }
            }
            .navigationTitle("Notes")
            .safeAreaInset(edge: .bottom) {
                Button(action: addNote) {
                    Text("New Note").font(.system(size: 17, weight: .semibold))
                        .frame(maxWidth: .infinity).padding().background(.blue).foregroundColor(.white).cornerRadius(12)
                }.padding()
            }
        }
    }
    func addNote() {}
}
